window.isIngredientInSeason = function(ingName, monthNum) {
  const m = Number(monthNum) || (new Date().getMonth() + 1);
  const lower = (ingName || "").toLowerCase();

  // Si conserve, coulis, surgelé ou sec -> toujours de saison (100%)
  if (
    lower.includes("conserve") ||
    lower.includes("surgelé") ||
    lower.includes("coulis") ||
    lower.includes("concassé") ||
    lower.includes("pulpe") ||
    lower.includes("séché") ||
    lower.includes("confit")
  ) {
    return { inSeason: true, reason: "Conservation / Placard" };
  }

  for (const rule of window.SEASONAL_PRODUCE_MONTHS) {
    if (rule.keywords.some((k) => lower.includes(k))) {
      const ok = rule.months.includes(m);
      return {
        inSeason: ok,
        reason: ok ? "Pleine saison" : "Hors pleine saison"
      };
    }
  }

  // Ingrédients d'épicerie, crémerie, viandes, poissons, œufs, pain -> disponibles toute l'année
  return { inSeason: true, reason: "Disponible toute l'année" };
};

window.evaluateRecipeSeasonality = function(recipe, monthNum) {
  const m = Number(monthNum) || (new Date().getMonth() + 1);
  const ings = (recipe && recipe.ingredients) || [];
  if (!ings.length) {
    return { pct: 100, inSeasonCount: 0, totalCount: 0, month: m };
  }

  let inSeasonScore = 0;
  let totalWeight = 0;

  ings.forEach((ing) => {
    const isProduce = ing.aisle === "Fruits & Légumes";
    // On donne un poids double aux Fruits & Légumes frais pour que le % reflète vraiment les produits frais de saison
    const weight = isProduce ? 2 : 1;
    totalWeight += weight;
    const check = window.isIngredientInSeason(ing.name, m);
    if (check.inSeason) {
      inSeasonScore += weight;
    }
  });

  const pct = Math.round((inSeasonScore / totalWeight) * 100);
  const inSeasonCount = ings.filter((i) => window.isIngredientInSeason(i.name, m).inSeason).length;

  return {
    pct,
    inSeasonCount,
    totalCount: ings.length,
    month: m
  };
};

window.evaluateRecipeNutriScore = function(recipe) {
  if (!recipe) {
    return { grade: "A", label: "Excellent équilibre", color: "#038141", bg: "#dcfce7" };
  }
  const title = (recipe.title || "").toLowerCase();
  const type = recipe.type || (recipe.style ? `dessert-${recipe.style}` : "weekday");
  const calMatch = String(recipe.calories || "").match(/(\d+)/);
  const kcal = calMatch ? parseInt(calMatch[1], 10) : 430;
  const ingsText = ((recipe.ingredients || []).map((i) => i.name.toLowerCase())).join(" ");

  let grade = "A";

  if (type === "weekday") {
    // Les plats de semaine Healthy oscillent entre A (très sain) et B (équilibré gourmand)
    const hasRichCheeseOrCream =
      ingsText.includes("crème") ||
      ingsText.includes("mozzarella") ||
      ingsText.includes("cheddar") ||
      ingsText.includes("emmental") ||
      ingsText.includes("comté") ||
      ingsText.includes("chèvre") ||
      ingsText.includes("jambon cru") ||
      ingsText.includes("serrano") ||
      ingsText.includes("bacon");
    grade = (kcal <= 435 && !hasRichCheeseOrCream) ? "A" : "B";
  } else if (type === "weekend-balanced") {
    const isVeryLean =
      title.includes("papillote") ||
      title.includes("cabillaud") ||
      title.includes("dorade") ||
      title.includes("bar") ||
      title.includes("taboulé") ||
      title.includes("poke") ||
      title.includes("brochettes") ||
      title.includes("tian");
    grade = isVeryLean ? "A" : "B";
  } else if (type === "gourmet") {
    const isLeanNoble =
      title.includes("saint-jacques") ||
      title.includes("cabillaud") ||
      title.includes("bar") ||
      title.includes("dorade") ||
      title.includes("gambas") ||
      title.includes("saumon") ||
      title.includes("truite");
    grade = isLeanNoble ? "B" : "C";
  } else if (type === "weekend-pleasure") {
    const isVeryRich =
      title.includes("tartiflette") ||
      title.includes("croziflette") ||
      title.includes("camembert") ||
      title.includes("reblochon") ||
      title.includes("burger") ||
      title.includes("carbonara") ||
      title.includes("entrecôte") ||
      title.includes("magret") ||
      kcal >= 650;
    grade = isVeryRich ? "D" : "C";
  } else if (type.startsWith("dessert")) {
    grade = recipe.style === "balanced" ? "B" : "D";
  }

  const metaByGrade = {
    A: { grade: "A", label: "Excellent équilibre nutritionnel", shortLabel: "Équilibre optimal", color: "#038141", bg: "#dcfce7" },
    B: { grade: "B", label: "Très bon équilibre alimentaire", shortLabel: "Bon équilibre", color: "#5da617", bg: "#ecfccb" },
    C: { grade: "C", label: "Équilibre modéré (Plaisir maîtrisé)", shortLabel: "Équilibre modéré", color: "#d97706", bg: "#fef9c3" },
    D: { grade: "D", label: "Plaisir gourmand occasionnel", shortLabel: "Plaisir gourmand", color: "#ea580c", bg: "#ffedd5" },
    E: { grade: "E", label: "Plaisir très riche", shortLabel: "Plaisir riche", color: "#dc2626", bg: "#fee2e2" }
  };

  return metaByGrade[grade] || metaByGrade.B;
};

(function attachCostsAndNutrition() {
  const db = window.RECIPES_DB;
  const costMap = db.estimatedCostsFor2 || {};
  const curMonth = new Date().getMonth() + 1;

  [
    ...(db.weekdayDinners || []),
    ...(db.weekendBalancedMeals || []),
    ...(db.weekendPleasureMeals || []),
    ...(db.gourmetMeals || [])
  ].forEach((r) => {
    if (typeof r.costFor2 !== 'number') {
      r.costFor2 =
        costMap[r.id] ||
        (r.type === 'gourmet' ? 14.50 : r.type === 'weekend-pleasure' ? 8.50 : 4.50);
    }
    if (r.difficulty === 'Moyenne') {
      r.difficulty = 'Facile';
    }
    const nutri = window.evaluateRecipeNutriScore(r);
    r.nutriScore = nutri.grade;
    r.nutriLabel = nutri.label;
    r.seasonalityPct = window.evaluateRecipeSeasonality(r, curMonth).pct;
  });

  (db.weekendDesserts || []).forEach((d) => {
    if (typeof d.costFor2 !== 'number') {
      d.costFor2 = costMap[d.id] || (d.style === 'gourmet' ? 2.60 : 2.30);
    }
    const nutri = window.evaluateRecipeNutriScore(d);
    d.nutriScore = nutri.grade;
    d.nutriLabel = nutri.label;
    d.seasonalityPct = window.evaluateRecipeSeasonality(d, curMonth).pct;
  });
})();
